import re
import unicodedata
from datetime import date, datetime, timedelta, timezone

from model_client import ModelClient
from patient_store import SESSION, find_by_identifier, resolve_authorized_patient
from tools.appointments import list_appointments
from tools.bills import list_bills
from tools.medications import list_medications
from tools.patient_profile import patient_profile

TOOLS = {
    \"patient_profile\": patient_profile,
    \"list_medications\": list_medications,
    \"list_bills\": list_bills,
    \"list_appointments\": list_appointments,
}

IDENTIFIER = re.compile(r\"(?<"'![0-9])(?:[0-9]{17}[0-9Xx]|1[0-9]{10})(?![0-9])")
DENIED = "无法查询该患者，请确认号码或家属授权。"
APPOINTMENT_FIELDS = {"date", "time", "department", "status"}


def _mask(match):
    value = match[0]
    return value[:3] + "****" + value[-4:] if len(value) == 11 else "[证件号已隐藏]"


def _redact(value):
    if isinstance(value, str):
        return IDENTIFIER.sub(_mask, unicodedata.normalize("NFKC", value))
    if isinstance(value, dict):
        return {_redact(key): _redact(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_redact(item) for item in value]
    if type(value) is int and IDENTIFIER.fullmatch(str(value)):
        return _redact(str(value))
    return value


class CustomerServiceAgent:
    def __init__(self, model_client=None):
        self.model = model_client or ModelClient()
        self.last_result = None
        self._login = None
        self._patient_ref = None
        self._appointments = None

    def _system_message(self):
        return {
            "role": "system",
            "content": ("你是医院客服助手。根据患者问题选择合适的工具。"
                        "预约查询使用 list_appointments，参数 date（YYYY-MM-DD）和 department（完整科室名）均可省略。"
                        "按上次预约列表的序号追问时仍用此工具，传从 1 开始的整数 index；"
                        "可传 field（date、time、department、status）只查询一个字段。"
                        "患者由服务端确定。工具返回后用中文回答，按返回顺序从 1 编号，不要编造。"),
            "tools": sorted(TOOLS),
            "today": datetime.now(timezone(timedelta(hours=8))).date().isoformat(),
        }

    def _send(self, messages):
        return self.model.send(_redact(messages))

    def answer(self, user_text):
        login = SESSION["login_patient_ref"]
        if self._login != login:
            self._login = self._patient_ref = login
            self._appointments = self.last_result = None

        user_text = unicodedata.normalize("NFKC", user_text)
        identifiers = IDENTIFIER.findall(user_text)
        if identifiers:
            self._appointments = self.last_result = None
            self._patient_ref = None
            refs = {find_by_identifier(value.upper()) for value in identifiers}
            if len(refs) != 1 or None in refs:
                return DENIED
            ref = refs.pop()
            try:
                resolve_authorized_patient(ref)
            except PermissionError:
                return DENIED
            self._patient_ref = ref

        messages = [self._system_message(), {"role": "user", "content": user_text}]
        first = self._send(messages)
        if not isinstance(first, dict) or "tool" not in first:
            return _redact(first) if isinstance(first, str) else "请说明您想查询的内容。"

        name = first["tool"]
        if not isinstance(name, str) or name not in TOOLS:
            return "暂不支持该查询。"
        arguments = first.get("arguments", {})
        if not isinstance(arguments, dict):
            return "请确认查询条件。"

        try:
            if name == "list_appointments":
                resolve_authorized_patient(self._patient_ref)
                if "index" in arguments:
                    index = arguments["index"]
                    if self._appointments is None:
                        return "请先查询预约列表。"
                    if type(index) is not int or not 1 <= index <= len(self._appointments):
                        return "上次的预约列表没有这一条。"
                    row = self._appointments[index - 1]
                    field = arguments.get("field")
                    if field is not None and (not isinstance(field, str) or field not in APPOINTMENT_FIELDS):
                        return "请确认要查询的预约信息。"
                    result = {field: row[field]} if field else row
                else:
                    self._appointments = None
                    filters = {key: arguments[key] for key in ("date", "department")
                               if key in arguments and arguments[key] is not None}
                    if any(not isinstance(value, str) or not value.strip() for value in filters.values()):
                        return "请确认查询条件。"
                    if "date" in filters and date.fromisoformat(filters["date"]).isoformat() != filters["date"]:
                        return "请输入有效的预约日期。"
                    result = list_appointments(self._patient_ref, **filters)
                    self._appointments = result["appointments"]
            else:
                arguments = dict(arguments)
                arguments["patient_ref"] = self._patient_ref
                result = TOOLS[name](**arguments)
        except PermissionError:
            self._appointments = self.last_result = None
            return DENIED
        except (TypeError, ValueError):
            return "请确认查询条件。"

        self.last_result = _redact(result)
        return _redact(self._send(messages + [
            {"role": "assistant", "tool_call": {"name": name}},
            {"role": "tool", "name": name, "content": self.last_result},
        ]))
